// Regenerates the typed API client sources from the OpenAPI snapshot in openapi/openapi.json.
//
//   bun run gen:api                          types from the committed snapshot (no Rust toolchain needed)
//   bun run gen:api --refresh <binary>       first replace the snapshot with `<binary> openapi`
//
// The snapshot is the server's own document, byte for byte (`sunnycloud openapi` equals
// `GET /api/v1/openapi.json`). CI runs this script and fails when the generated files differ from the commit.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const root = new URL('../', import.meta.url);
const snapshot = fileURLToPath(new URL('openapi/openapi.json', root));
const schemaOut = fileURLToPath(new URL('src/lib/api/generated/schema.d.ts', root));
const codesOut = fileURLToPath(new URL('src/lib/api/generated/problem-codes.ts', root));

const args = process.argv.slice(2);
const refreshAt = args.indexOf('--refresh');
if (refreshAt !== -1) {
  const binary = args[refreshAt + 1];
  if (!binary) {
    throw new Error('--refresh needs the path of the sunnycloud binary');
  }
  const document = execFileSync(binary, ['openapi'], { maxBuffer: 64 * 1024 * 1024 });
  writeFileSync(snapshot, document);
}

const text = readFileSync(snapshot, 'utf8');
const document = JSON.parse(text);

const ast = await openapiTS(document);
writeFileSync(
  schemaOut,
  `// Generated by scripts/gen-api.mjs from openapi/openapi.json. Do not edit.\n${astToString(ast)}`,
);

const codes = document.components.schemas.Problem.properties.code.enum;
if (!Array.isArray(codes) || codes.length === 0) {
  throw new Error('the Problem schema of the snapshot lists no error codes');
}
const items = codes.map((code) => `  '${code}',`).join('\n');
writeFileSync(
  codesOut,
  `// Generated by scripts/gen-api.mjs from openapi/openapi.json. Do not edit.\n` +
    `export const PROBLEM_CODES: ReadonlySet<string> = new Set([\n${items}\n]);\n`,
);
